# Dummy data generation - note this code was generated by ChatGPT 
# and modified as appropriate #

library(dplyr)
library(lubridate)
library(readr)
library(tidyr)


set.seed(2026)

n <- 10000
years <- 2019:2025
dir.create("output", showWarnings = FALSE, recursive = TRUE)

# Helper functions
random_date <- function(start, end, n) {
  start <- as.Date(start)
  end <- as.Date(end)
  start + sample.int(as.integer(end - start) + 1, n, replace = TRUE) - 1
}

event_date <- function(n, probability, start, end) {
  x <- as.Date(rep(NA_character_, n))
  has_event <- runif(n) < probability
  x[has_event] <- random_date(start, end, sum(has_event))
  x
}

# ----------------------------------------
# 1. Common dataset
# ----------------------------------------

common <- tibble(
  patient_id = seq_len(n),
  sex = sample(c("male", "female"), n, TRUE),
  dob = random_date("1930-01-01", "1973-01-31", n),
  ethnicity_primary = sample(
    c("1", "2", "3", "4", "5", NA_character_),
    n, TRUE, prob = c(.45, .12, .10, .08, .05, .2)
  ),
  ethnicity_cat = sample(
    c("White", "Asian", "Black", "Mixed", "Other", NA),
    n, TRUE, prob = c(.70, .12, .07, .04, .04, .03)
  ),
  practice_deregistration_date = as.Date(NA),
  death_date = event_date(n, .08, "2019-02-02", "2025-12-31"),
  household_size = sample(1:6, n, TRUE),
  prostate_cancer = as.Date(NA),
  pregnancy = as.Date(NA),
  hrtcocp = as.Date(NA),
  hf_exclude_date = as.Date(NA),
  hf_diagnosis_primary_date = event_date(
    n, .065, "2019-02-01", "2025-12-31"
  ),
  hf_diagnosis_apc_date = event_date(
    n, .045, "2019-02-01", "2025-12-31"
  ),
  hf_diagnosis_ec_date = event_date(
    n, .025, "2019-02-01", "2025-12-31"
  ),
  hf_death_date = as.Date(NA),
  hf_mi_diagnosis_apc_date = event_date(
    n, .025, "2019-02-01", "2025-12-31"
  ),
  first_t2dm_date = event_date(n, .20, "2000-01-01", "2025-12-31"),
  first_copd_date = event_date(n, .12, "2000-01-01", "2025-12-31"),
  first_hypertension_date = event_date(
    n, .35, "2000-01-01", "2025-12-31"
  ),
  first_af_date = event_date(n, .13, "2000-01-01", "2025-12-31"),
  first_ihd_date = event_date(n, .16, "2000-01-01", "2025-12-31"),
  first_ckd_date = event_date(n, .14, "2000-01-01", "2025-12-31")
) %>%
  mutate(
    patient_index_date = pmax(dob %m+% years(45), as.Date("2019-02-01")),
    hf_diagnosis_emerg_date = pmin(
      hf_diagnosis_apc_date, hf_diagnosis_ec_date, na.rm = TRUE
    ),
    hf_diagnosis_date = pmin(
      hf_diagnosis_primary_date,
      hf_diagnosis_emerg_date,
      hf_death_date,
      na.rm = TRUE
    )
  )

# Ensure no HF diagnosis occurs after death.
# For testing purposes, patients remain eligible until
# the earliest applicable exclusion or death date.
common <- common %>%
  mutate(
    hf_diagnosis_primary_date = if_else(
      !is.na(death_date) & hf_diagnosis_primary_date > death_date,
      as.Date(NA), hf_diagnosis_primary_date
    ),
    hf_diagnosis_apc_date = if_else(
      !is.na(death_date) & hf_diagnosis_apc_date > death_date,
      as.Date(NA), hf_diagnosis_apc_date
    )
  )

write_csv(common, "analysis/dummy_data/dummy_dataset_wp1_common.csv.gz", na = "")

# ----------------------------------------
# 2. Annual time-dependent datasets
# ----------------------------------------

for (yr in years) {

  index_date <- as.Date(paste0(yr, "-02-01"))

  annual <- common %>%
    filter(
      dob %m+% years(45) <= index_date,
      dob %m+% years(110) > index_date
     # is.na(death_date) | death_date > index_date,
     # is.na(hf_exclude_date) | hf_exclude_date > index_date
    ) %>%
    mutate(
      age = floor(time_length(interval(dob, index_date), "years")),
      reg_start_date = index_date %m-% years(2),
      reg_end_date = as.Date("2025-12-31"),

      region = sample(
        c("North East", "North West", "Yorkshire and The Humber", "East Midlands", 
            "West Midlands", "East", "London", "South East", "South West", NA_character_),
            prob = c(rep(.106, 9), .05), n(), TRUE
      ),
      imd_decile = sample(
        c("1 (most deprived)", "2", "3", "4", "5", "6", "7", "8", "9", "10 (least deprived)", "unknown"),
        prob = c(rep(.097, 10), .03), n(), TRUE
      ),
      rural_urban = sample(
        c(1:8, NA_integer_), n(), TRUE
      ),

      smoking = sample(
        c("S", "E", "N", NA_character_),
        n(), TRUE, prob = c(.18, .30, .47, .05)
      ),

      bmi_value = if_else(
        runif(n()) < .12,
        NA_real_,
        round(pmin(pmax(rnorm(n(), 28, 5.5), 14), 55), 1)
      ),

      obesity = coalesce(bmi_value >= 30, FALSE) |
        runif(n()) < .04,

      carehome_at_index = runif(n()) < .035,
      migrant = runif(n()) < .08,
      non_english_speaking = runif(n()) < .05,
      learndis = runif(n()) < .025,
      smi = runif(n()) < .07,
      substance_abuse_1yr = runif(n()) < .045,
      homeless_1yr = runif(n()) < .015,
      housebound_1yr = runif(n()) < .06,
    )
  
  annual <- annual %>%
    mutate(
      across(
        where(is.logical),
        ~ case_when(
          is.na(.) ~ NA_character_,
          . ~ "T",
          TRUE ~ "F"
        )
      )
    )
  
  write_csv(
    annual,
    sprintf("analysis/dummy_data/dummy_dataset_wp1_%s.csv.gz", yr),
    na = ""
  )
}

message("Dummy WP1 dataset generation complete.")
